-- Issue numbers (#1, #2, …) per workspace. Generated by drizzle-kit, then
-- extended by hand: existing tasks are numbered (oldest first, ties broken by
-- id) BEFORE the unique and check constraints are added, and the counters
-- start after the highest backfilled number. Assignment of new numbers and
-- immutability live in 0017_task_numbers_security.sql.
LOCK TABLE "tasks" IN SHARE ROW EXCLUSIVE MODE;--> statement-breakpoint
CREATE TABLE "task_number_counters" (
	"workspace_id" uuid PRIMARY KEY NOT NULL,
	"last_number" integer NOT NULL,
	CONSTRAINT "task_number_counters_positive" CHECK ("task_number_counters"."last_number" > 0)
);
--> statement-breakpoint
ALTER TABLE "tasks" ADD COLUMN "number" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
UPDATE "tasks" AS t
   SET "number" = s.rn
  FROM (
    SELECT id, row_number() OVER (PARTITION BY workspace_id ORDER BY created_at, id) AS rn
      FROM "tasks"
  ) AS s
 WHERE t.id = s.id;--> statement-breakpoint
INSERT INTO "task_number_counters" ("workspace_id", "last_number")
SELECT workspace_id, max("number") FROM "tasks" GROUP BY workspace_id;--> statement-breakpoint
ALTER TABLE "task_number_counters" ADD CONSTRAINT "task_number_counters_workspace_id_workspaces_id_fk" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_workspace_number_uq" UNIQUE("workspace_id","number");--> statement-breakpoint
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_number_positive" CHECK ("tasks"."number" > 0);
